<script lang="ts">
 import {app,run,usage,notify} from '../app.svelte';import {claimStore} from '../store';import {download,exportCSV} from '../exports';import {validateBackup} from '../backup';import {todayLocal} from '../sample';import type {Backup} from '../types';import Icon from '../components/Icon.svelte';import Modal from '../components/Modal.svelte';
 let {screen}:{screen:string}=$props();let pending=$state(''),preview=$state<Backup|null>(null),reset=$state<'sample'|'fresh'|null>(null),busy=$state(false);
 const data=$derived(app.data!);const actor=$derived(data.users.find(u=>u.id===data.session?.userId)!);const finance=$derived(actor.role==='Finance');const due=$derived(Date.now()-Date.parse(data.lastBackup||data.createdAt)>7*86400000);
 async function backup(){busy=true;await run(async()=>{download(await claimStore.backup(),'claimease-backup-'+todayLocal()+'.json','application/json');},'Backup downloaded. Keep it somewhere safe.');busy=false;}
 async function importFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>30*1024*1024)throw new Error('Backup exceeds the 30 MB import limit.');pending=await file.text();preview=validateBackup(pending);}catch(e){pending='';preview=null;notify((e as Error).message);}(e.target as HTMLInputElement).value='';}
 async function restore(){busy=true;const result=await run(()=>claimStore.importBackup(pending));if(result){notify(result);pending='';preview=null;usage();}busy=false;}
 function csv(kind:'claims'|'lines'|'batches'|'accounting'){download(exportCSV(kind,data,todayLocal(),c=>claimStore.findings(c)),`claimease-${kind}.csv`,'text/csv');}
</script>
{#if screen==='/privacy'}<div class="page-header"><div><p class="eyebrow">YOUR DATA STAYS WITH YOU</p><h1>Privacy & backup</h1><p>No cloud. No tracking. No data sent to a server.</p></div>{#if finance}<button class="primary" disabled={busy} onclick={backup}><Icon name="download" size={17}/>Export JSON backup</button>{/if}</div>{#if due}<div class="notice warning-notice"><Icon name="warning"/><p><strong>Your backup is overdue.</strong> More than 7 days have passed since {data.lastBackup?'your last backup':'this workspace was created'}. {finance?'Download a new backup now.':'Ask the Finance demo account to export a full backup.'}</p></div>{/if}<div class="dashboard-grid"><section class="panel form-panel"><div class="panel-heading"><h2>Only in this browser</h2><Icon name="lock"/></div><p>Claim details, policies, demo accounts, session information and audit entries are stored in <strong>localStorage</strong>. Receipt images are stored in <strong>IndexedDB</strong>.</p><p>Nothing is uploaded. Clearing browser data, switching devices or using another browser does not carry this workspace with you. Browser quotas and private-browsing rules may limit storage.</p><div class="privacy-metrics"><div><span>Claim metadata</span><strong>{(app.usage.metadata/1024).toFixed(0)} KB / ~5 MB</strong><meter min="0" max="5242880" value={app.usage.metadata} aria-label="Local metadata usage"></meter></div><div><span>Receipt images</span><strong>{(app.usage.receipts/1048576).toFixed(2)} MB</strong><small>Each compressed image is under 200 KB.</small></div></div><button onclick={usage}>Refresh storage meter</button></section><section class="panel form-panel"><div class="panel-heading"><h2>A backup is your safety net</h2><Icon name="download"/></div><p>Last backup: <strong>{data.lastBackup?new Date(data.lastBackup).toLocaleString('en-IN'):'Not yet exported'}</strong></p><p>A full JSON backup includes receipt images, audit history, demo accounts and their password hashes. It excludes active sessions and login lockouts. Keep backups private.</p>{#if finance}<label class="file-upload">Import a ClaimEase backup<input type="file" accept="application/json,.json" onchange={importFile}/></label><p class="field-help">30 MB maximum. You’ll see a preview before confirming. Existing claims are never overwritten. Conflicting policy or receipt identifiers stop the import.</p>{:else}<div class="notice"><Icon name="shield"/><p>Full-browser backup and restore are Finance-only because the file contains every demo employee’s claims. Export your own claims as CSV or PDF instead.</p></div><button onclick={()=>csv('claims')}>Export my claims CSV</button>{/if}</section></div>
{:else if screen==='/settings'}<div class="page-header"><div><p class="eyebrow">FINANCE ADMINISTRATION</p><h1>Workspace settings</h1><p>Simple exports, local data controls and a fresh start when you need one.</p></div><a class="button primary" href="/policy">Manage expense policy<Icon name="arrow" size={17}/></a></div><section class="panel form-panel"><div class="panel-heading"><div><h2>Data exports</h2><p>Simple files, not an accounting integration. General-ledger codes are set in the policy.</p></div><Icon name="download"/></div><div class="export-grid">{#each ['claims','lines','batches','accounting'] as kind}<button onclick={()=>csv(kind as 'claims'|'lines'|'batches'|'accounting')}><Icon name="download"/><span><strong>{kind[0].toUpperCase()+kind.slice(1)} CSV</strong><small>{kind==='accounting'?'Finance approved & paid lines, GL and cost centre':kind==='lines'?'Expense details and policy findings':kind==='batches'?'Payment records and totals':'Claim headers, totals and findings'}</small></span><Icon name="arrow" size={16}/></button>{/each}</div></section><section class="panel form-panel"><div class="panel-heading"><h2>Appearance</h2></div><div class="button-group"><button class:chosen={data.theme==='light'} onclick={()=>run(()=>claimStore.setTheme('light'))}><Icon name="sun"/>Light theme</button><button class:chosen={data.theme==='dark'} onclick={()=>run(()=>claimStore.setTheme('dark'))}><Icon name="moon"/>Dark theme</button></div></section><section class="panel form-panel"><div class="panel-heading"><h2>Demo data controls</h2><Icon name="settings"/></div><p>Export a backup first. These actions replace the visible claims and batches, but never remove the append-only audit or reuse claim numbers. Receipt images remain local so earlier evidence is not silently destroyed.</p><div class="button-group"><button onclick={()=>reset='sample'}>Load sample data</button><button class="danger-text" onclick={()=>reset='fresh'}>Start fresh</button></div></section>
{:else if screen==='/notifications'}<div class="page-header"><div><p class="eyebrow">STAY IN THE LOOP</p><h1>Notifications</h1><p>Updates and waiting approvals in this browser. No emails are sent.</p></div><button class="primary" onclick={()=>run(()=>claimStore.markRead(),'Notifications marked as read.')}><Icon name="check" size={17}/>Mark all read</button></div><section class="panel"><div class="notification-list">{#each data.claims.filter(c=>actor.role==='Manager'?c.status==='Submitted':actor.role==='Finance'?c.status==='Manager approved':c.status==='Returned for correction') as c}<a href={'/claims/'+c.id}><span class="summary-icon"><Icon name="clock"/></span><div><strong>{actor.role==='Employee'?'Correction requested':'Waiting for your review'}</strong><p>{c.number} · {c.title}</p></div><Icon name="chevron" size={17}/></a>{/each}{#each [...data.audit].filter(a=>a.actorId!==actor.id).reverse().slice(0,20) as event}<a href={'/claims/'+event.claimId}><span class="summary-icon"><Icon name="bell"/></span><div><strong>{event.status}</strong><p>{event.comment}</p><small>{new Date(event.time).toLocaleString('en-IN')}{event.time>(data.notificationsRead[actor.id]||'')?' · Unread':' · Read'}</small></div><Icon name="chevron" size={17}/></a>{/each}{#if !data.audit.length}<div class="empty-state"><Icon name="bell" size={32}/><h3>You’re all caught up</h3><p>Status changes will appear here.</p></div>{/if}</div></section>
{:else}<div class="page-header"><div><p class="eyebrow">CLAIM IT. CLEAR IT.</p><h1>A simpler way to settle up.</h1><p>ClaimEase is a free, single-browser expense claim demo.</p></div><span class="app-version">VERSION 1.0</span></div><section class="about-hero panel"><div class="about-mark"><img src="/favicon.svg" alt="ClaimEase logo"/></div><h2>Less paperwork.<br/>More peace of mind.</h2><p>Employees record expenses. The policy engine checks every line. Managers make clear decisions. Finance records reimbursement—with a complete history at every step.</p></section><div class="dashboard-grid"><section class="panel form-panel"><h2>What this demo does</h2><ul class="feature-list"><li><Icon name="check"/>Checks limits, receipts, dates and duplicate expenses.</li><li><Icon name="check"/>Keeps claims and receipts on this device.</li><li><Icon name="check"/>Records approvals, corrections and payment batches.</li><li><Icon name="check"/>Creates PDF, CSV and backup files in your browser.</li></ul></section><section class="panel form-panel"><h2>What it does not do</h2><p>This is <strong>not a production office system</strong>. A real office needs a server, real login, secure access controls, reliable backups and multi-device synchronisation.</p><p>Demo sign-in runs entirely in the browser and is not secure. Browser owners can inspect or modify local data. Do not use real receipts, real passwords or confidential business information.</p><p>Vercel’s free Hobby plan is intended for personal, non-commercial use. No money is transferred, and CSV files are not an accounting integration.</p></section></div><div class="about-footer"><Icon name="shield"/><p>Kestrel Labs, all people, vendors and receipts are fictional.<br/>No API keys, AI services, analytics or cloud database.</p></div>{/if}
{#if preview}<Modal title="Review backup import" onclose={()=>{preview=null;pending='';}}><p>This backup contains <strong>{preview.data.claims.length} claims</strong>, {preview.receipts.length} receipt images and {preview.data.audit.length} audit entries.</p><p>Exported {new Date(preview.exportedAt).toLocaleString('en-IN')}. Existing claim IDs and numbers will be skipped. Nothing is silently overwritten. Policy or image conflicts stop the import.</p><div class="modal-actions"><button onclick={()=>{preview=null;pending='';}}>Cancel</button><button class="primary" disabled={busy} onclick={restore}>Confirm safe merge</button></div></Modal>{/if}
{#if reset}<Modal title={reset==='sample'?'Load fictional sample data?':'Start a fresh workspace?'} onclose={()=>reset=null}><p>{reset==='sample'?'Replace the visible claims with 30 fictional claims and two payment batches?':'Remove all visible claims and payment batches? Demo accounts and policy history remain.'}</p><p>This cannot be undone in the app. Export a JSON backup first. Prior audit entries and retired claim numbers are retained.</p><div class="modal-actions"><button onclick={()=>reset=null}>Cancel</button><button class="danger-button" disabled={busy} onclick={async()=>{busy=true;await run(()=>claimStore.reset(reset==='sample'),'Workspace updated. Earlier audit retained.');reset=null;busy=false;usage();}}>Confirm {reset==='sample'?'load sample data':'start fresh'}</button></div></Modal>{/if}